import{_ as o,r as s,o as p,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Task Scheduling - October CMS - 4.x","titleTemplate":false,"description":"Perform scheduled tasks for just about anything.","frontmatter":{"subtitle":"Perform scheduled tasks for just about anything."},"headers":[{"level":2,"title":"Defining Schedules","slug":"defining-schedules","link":"#defining-schedules","children":[{"level":3,"title":"Schedule Frequency Options","slug":"schedule-frequency-options","link":"#schedule-frequency-options","children":[{"level":4,"title":"Truth Test Constraints","slug":"truth-test-constraints","link":"#truth-test-constraints","children":[]}]},{"level":3,"title":"Preventing Task Overlaps","slug":"preventing-task-overlaps","link":"#preventing-task-overlaps","children":[]}]},{"level":2,"title":"Task Output","slug":"task-output","link":"#task-output","children":[]},{"level":2,"title":"Task Hooks","slug":"task-hooks","link":"#task-hooks","children":[{"level":4,"title":"Pinging URLs","slug":"pinging-urls","link":"#pinging-urls","children":[]}]}],"relativePath":"4.x/extend/system/scheduling.md","filePath":"4.x/extend/system/scheduling.md"}'),u={name:"4.x/extend/system/scheduling.md"};function d(r,n,k,h,g,m){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Task Scheduling",-1)),a(e),n[1]||(n[1]=i(`<div class="custom-block aside"><p>See the <a href="./../../setup/installation.html">installation guide</a> for instructions on how to set up the scheduler task.</p></div><p>In the past, developers have generated a Cron entry for each task they need to schedule. However, this can sometimes be a headache. Your task schedule is no longer in source control, and you must SSH into your server to add the Cron entries. The command scheduler allows you to fluently and expressively define your command schedule within the application itself, and only a single Cron entry is needed on your server.</p><p><a id="oc-defining-schedules"></a></p><h2 id="defining-schedules"><a href="#defining-schedules" class="header-anchor">#</a> Defining Schedules</h2><p>You may define all of your scheduled tasks by overriding the <code>registerSchedule</code> method inside the <a href="./../extending.html">plugin registration file</a>. The method will take a single <code>$schedule</code> argument and is used for defining commands along with their frequency.</p><p>To get started, let&#39;s look at an example of scheduling a task. In this example, we will schedule a <code>Closure</code> to be called every day at midnight. Within the <code>Closure</code> we will execute a database query to clear a table:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSchedule</span><span class="token punctuation">(</span><span class="token variable">$schedule</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;recent_users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In addition to scheduling <code>Closure</code> calls, you may also schedule <a href="./../console-commands.html">console commands</a> and operating system commands. For example, you may use the <code>command</code> method to schedule a console command:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cache:clear&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>exec</code> command may be used to issue a command to the operating system:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;node /home/acme/script.js&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="schedule-frequency-options"><a href="#schedule-frequency-options" class="header-anchor">#</a> Schedule Frequency Options</h3><p>Of course, there are a variety of schedules you may assign to your task:</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>-&gt;cron(&#39;* * * * *&#39;);</code></td><td>Run the task on a custom Cron schedule</td></tr><tr><td><code>-&gt;everyMinute();</code></td><td>Run the task every minute</td></tr><tr><td><code>-&gt;everyFiveMinutes();</code></td><td>Run the task every five minutes</td></tr><tr><td><code>-&gt;everyTenMinutes();</code></td><td>Run the task every ten minutes</td></tr><tr><td><code>-&gt;everyThirtyMinutes();</code></td><td>Run the task every thirty minutes</td></tr><tr><td><code>-&gt;hourly();</code></td><td>Run the task every hour</td></tr><tr><td><code>-&gt;daily();</code></td><td>Run the task every day at midnight</td></tr><tr><td><code>-&gt;dailyAt(&#39;13:00&#39;);</code></td><td>Run the task every day at 13:00</td></tr><tr><td><code>-&gt;twiceDaily(1, 13);</code></td><td>Run the task daily at 1:00 &amp; 13:00</td></tr><tr><td><code>-&gt;weekly();</code></td><td>Run the task every week</td></tr><tr><td><code>-&gt;monthly();</code></td><td>Run the task every month</td></tr></tbody></table></div><p>These methods may be combined with additional constraints to create even more finely tuned schedules that only run on certain days of the week. For example, to schedule a command to run weekly on Monday:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Runs once a week on Monday at 13:00...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">weekly</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">mondays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">at</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;13:00&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Below is a list of the additional schedule constraints:</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>-&gt;weekdays();</code></td><td>Limit the task to weekdays</td></tr><tr><td><code>-&gt;sundays();</code></td><td>Limit the task to Sunday</td></tr><tr><td><code>-&gt;mondays();</code></td><td>Limit the task to Monday</td></tr><tr><td><code>-&gt;tuesdays();</code></td><td>Limit the task to Tuesday</td></tr><tr><td><code>-&gt;wednesdays();</code></td><td>Limit the task to Wednesday</td></tr><tr><td><code>-&gt;thursdays();</code></td><td>Limit the task to Thursday</td></tr><tr><td><code>-&gt;fridays();</code></td><td>Limit the task to Friday</td></tr><tr><td><code>-&gt;saturdays();</code></td><td>Limit the task to Saturday</td></tr><tr><td><code>-&gt;when(Closure);</code></td><td>Limit the task based on a truth test</td></tr></tbody></table></div><h4 id="truth-test-constraints"><a href="#truth-test-constraints" class="header-anchor">#</a> Truth Test Constraints</h4><p>The <code>when</code> method may be used to limit the execution of a task based on the result of a given truth test. In other words, if the given <code>Closure</code> return <code>true</code>, the task will execute as long as no other constraining conditions prevent the task from running:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="preventing-task-overlaps"><a href="#preventing-task-overlaps" class="header-anchor">#</a> Preventing Task Overlaps</h3><p>By default, scheduled tasks will be run even if the previous instance of the task is still running. To prevent this, you may use the <code>withoutOverlapping</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withoutOverlapping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>In this example, the <code>emails:send</code> console command will be run every minute if it is not already running. The <code>withoutOverlapping</code> method is especially useful if you have tasks that vary drastically in their execution time, preventing you from needing to predict exactly how long a given task will take.</p><h2 id="task-output"><a href="#task-output" class="header-anchor">#</a> Task Output</h2><p>The scheduler provides several convenient methods for working with the output generated by scheduled tasks. First, using the <code>sendOutputTo</code> method, you may send the output to a file for later inspection.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Using the <code>emailOutputTo</code> method, you may e-mail the output to an e-mail address of your choice. Note that the output must first be sent to a file using the <code>sendOutputTo</code> method. Also before e-mailing the output of a task, you should configure <a href="./../../setup/mail-config.html">mail services</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">emailOutputTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.tld&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>The <code>emailOutputTo</code> and <code>sendOutputTo</code> methods are exclusive to the <code>command</code> method and are not supported for <code>call</code>.</p></div><h2 id="task-hooks"><a href="#task-hooks" class="header-anchor">#</a> Task Hooks</h2><p>Using the <code>before</code> and <code>after</code> methods, you may specify code to be executed before and after the scheduled task is complete:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Task is about to start...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Task is complete...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="pinging-urls"><a href="#pinging-urls" class="header-anchor">#</a> Pinging URLs</h4><p>Using the <code>pingBefore</code> and <code>thenPing</code> methods, the scheduler can automatically ping a given URL before or after a task is complete. This method is useful for notifying an external service that your scheduled task is commencing or complete:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">pingBefore</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">thenPing</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,37))])}const v=o(u,[["render",d]]);export{y as __pageData,v as default};
